    const issued = issueInvoice(draft, invoices.map((inv) => inv.number || '')).value;
    invoices.push(issued);
  }

  const result = dashboard(invoices, '2026-10-20');

  assert(result.topCustomers.length <= 3);
});

test('dashboard with multiple invoices per customer', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-15',
      lines: [{ sku: 'ICON-SET', qty: 5 }],
    }).value,
    [inv1.number]
  ).value;

  const result = dashboard([inv1, inv2], '2026-10-20');

  const c001 = result.topCustomers.find((c) => c.customerId === 'C-001');
  assert(c001);
  assert(c001.due > 0);
});

test('dashboard structure has all fields', () => {
  const result = dashboard([], '2026-10-20');

  assert('counts' in result);
  assert('outstanding' in result);
  assert('overdue' in result);
  assert('topCustomers' in result);
  assert('draft' in result.counts);
  assert('issued' in result.counts);
  assert('partially_paid' in result.counts);
  assert('paid' in result.counts);
  assert('count' in result.overdue);
  assert('amount' in result.overdue);
});

test('dashboard counts are non-negative integers', () => {
  const invoices = createTestInvoices();
  const result = dashboard(invoices, '2026-10-20');

  assert(result.counts.draft >= 0);
  assert(result.counts.issued >= 0);
  assert(result.counts.partially_paid >= 0);
  assert(result.counts.paid >= 0);
  assert(Number.isInteger(result.counts.draft));
  assert(Number.isInteger(result.counts.issued));
});

test('dashboard outstanding is non-negative integer', () => {
  const invoices = createTestInvoices();
  const result = dashboard(invoices, '2026-10-20');

  assert(result.outstanding >= 0);
  assert(Number.isInteger(result.outstanding));
});

test('dashboard overdue count and amount are integers', () => {
  const invoices = createTestInvoices();
  const result = dashboard(invoices, '2026-10-20');

  assert(Number.isInteger(result.overdue.count));
  assert(Number.isInteger(result.overdue.amount));
});

test('dashboard topCustomers due amounts are integers', () => {
  const invoices = createTestInvoices();
  const result = dashboard(invoices, '2026-10-20');

  result.topCustomers.forEach((customer) => {
    assert(Number.isInteger(customer.due));
  });
});

test('dashboard does not count draft in outstanding', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = dashboard([draft], '2026-10-20');

  assert.equal(result.outstanding, 0);
});

test('dashboard with partial and paid invoices', () => {
  const invoices = createTestInvoices();
  const { total: total1 } = invoiceTotals(invoices[0]);
  const partial = recordPayment(invoices[0], {
    amount: 5000,
    date: '2026-10-15',
  }).value;

  const { total: total2 } = invoiceTotals(invoices[1]);
  const paid = recordPayment(invoices[1], {
    amount: total2,
    date: '2026-10-15',
  }).value;

  const mixed = [partial, paid, invoices[2]];
  const result = dashboard(mixed, '2026-10-20');

  assert.equal(result.counts.partially_paid, 1);
  assert.equal(result.counts.paid, 1);
  assert.equal(result.counts.issued, 1);
});

